/**
 * Helpers for Grid 3 image references and auto-generated cell labels.
 *
 * Grid 3 keyboard gridsets commonly have image-only action cells: the cell
 * carries an image reference (e.g. `[GRID3X]delete_letter.wmf`) and no
 * caption. Two things fall out of that:
 *
 * 1. Browsers cannot render WMF, so built-in [GRID3X] symbols need a glyph
 *    fallback (the built-in set is small and predictable).
 * 2. The aac-processors loader gives caption-less cells synthetic labels
 *    (`Cell_43`, `AutoContent_7`, `"Chat Workspace"`), which should not be
 *    shown to users when we can derive something better from the image
 *    reference.
 */

/**
 * Fallback glyphs for Grid 3 built-in [GRID3X] symbols, keyed by the symbol
 * name parsed from the reference (`[GRID3X]delete_letter.wmf` →
 * `delete_letter`).
 */
export const GRID3X_GLYPHS: Record<string, string> = {
  delete_letter: '⌫',
  delete_word: '⌦',
  backspace: '⌫',
  clear: '🧹',
  enter: '↵',
  shift: '⇧',
  undo: '↶',
  redo: '↷',
  speak: '🔊',
  speak_all: '🔊',
  speak_nothing: '🔇',
  space: '␣',
  tab: '⇥',
  keyboard: '⌨',
  keyboard_hide: '⌨',
  hide_keyboard: '⌨',
  globe: '🌐',
  left: '←',
  right: '→',
  up: '↑',
  down: '↓',
  home: '⌂',
};

/**
 * Grid 3 dynamic image files are coordinate-named (`{x}-{y}-0-text-0.png`
 * under `Grids/<page>/`). A name like that carries no meaning for users, so
 * label derivation treats it as underivable.
 */
const COORDINATE_IMAGE_NAME = /^\d+-\d+-/;

/**
 * Extract a normalised symbol name from a Grid 3 image reference.
 *
 * Handles bracketed library references — `[GRID3X]name.wmf`,
 * `[Widgit]computer/keyboard.png` (the last path segment is used) — and
 * plain filenames/paths.
 */
export function grid3ImageName(imageRef?: string | null): string | null {
  if (!imageRef || typeof imageRef !== 'string') return null;
  const bracketMatch = imageRef.match(/^\[[^\]]+\](?:([^/\]]*\/)*([^/]+?))(?:\.[^.]*)?$/);
  const fromBracket = bracketMatch ? bracketMatch[2] : null;
  const base = fromBracket || imageRef.split('/').pop() || imageRef;
  const noExt = base.replace(/\.[^.]+$/, '');
  return noExt ? noExt.toLowerCase() : null;
}

/**
 * Best-effort glyph for an image reference. Exact [GRID3X] names first,
 * then fuzzy rules for spelling variants. Fuzzy stems are matched only
 * when followed by a separator or end-of-name, so `tablet`, `tabby_cat`
 * or `spaceship` never match the `tab`/`space` rules.
 */
const startsWithStem = (name: string, stem: string) =>
  name.startsWith(stem) && (name.length === stem.length || /^[_-]/.test(name.slice(stem.length)));

export function glyphForGrid3Image(imageRef?: string | null): string | null {
  const name = grid3ImageName(imageRef);
  if (!name) return null;
  if (GRID3X_GLYPHS[name]) return GRID3X_GLYPHS[name];
  if (startsWithStem(name, 'delete') && /letter/.test(name)) return '⌫';
  if (startsWithStem(name, 'delete') && /word/.test(name)) return '⌦';
  if (startsWithStem(name, 'delete')) return '⌫';
  if (startsWithStem(name, 'backspace')) return '⌫';
  if (startsWithStem(name, 'enter')) return '↵';
  if (startsWithStem(name, 'shift')) return '⇧';
  if (startsWithStem(name, 'undo')) return '↶';
  if (startsWithStem(name, 'redo')) return '↷';
  if (startsWithStem(name, 'speak')) return '🔊';
  if (startsWithStem(name, 'space')) return '␣';
  if (startsWithStem(name, 'tab')) return '⇥';
  if (startsWithStem(name, 'keyboard')) return '⌨';
  return null;
}

/**
 * True for the synthetic labels the aac-processors loader assigns to
 * caption-less cells (`Cell_43`, `AutoContent_7`).
 */
export function isAutoGeneratedCellLabel(label?: string | null): boolean {
  return !!label && /^(Cell|AutoContent)_\d+$/.test(label);
}

/**
 * Derive a friendly label for a caption-less cell from its image reference
 * (`Cell_43` + `[GRID3X]delete_letter.wmf` → `delete letter`). Returns null
 * when nothing better than the raw label can be derived — including
 * coordinate-named images (`2-3-0-text-0`), which would otherwise produce
 * meaningless number soup.
 */
export function friendlyCellLabel(
  label?: string | null,
  imageRef?: string | null
): string | null {
  if (!isAutoGeneratedCellLabel(label)) return null;
  const name = grid3ImageName(imageRef);
  if (!name || COORDINATE_IMAGE_NAME.test(name)) return null;
  return name.replace(/[_-]+/g, ' ');
}

/**
 * True when `label` looks like the loader's default display name for a
 * Workspace cell — the bare `Workspace` or the subtyped `Chat Workspace` /
 * `Keyboard Workspace` forms. Note the check is shape-based: any label
 * *ending* in "workspace" (e.g. a genuine "Writing workspace" caption)
 * matches too, which is accepted as the cost of a simple default filter.
 */
export function isDefaultWorkspaceLabel(label?: string | null): boolean {
  if (!label) return false;
  const trimmed = label.trim();
  return /(?:^|\s)workspace$/i.test(trimmed);
}

/**
 * One-stop presentation derivation for a cell, shared by the React and Vue
 * renderers (main grid and toolbar):
 *
 * - `glyph`: fallback glyph when the image cannot be rendered
 * - `displayLabel`: the label to show (derived when possible, raw otherwise)
 * - `hideLabel`: the label should not be shown at all (synthetic label with
 *   a glyph or image doing the talking)
 * - `alt`: accessible name for the image/glyph (empty when the raw label is
 *   synthetic and nothing better was derived)
 */
export function deriveCellPresentation(
  button: { label?: string | null | undefined; message?: string | null | undefined },
  imageRef: string | null | undefined,
  hasRenderableImage: boolean
): { glyph: string | null; displayLabel: string; hideLabel: boolean; alt: string } {
  // The glyph is always derived: it is used when there is no renderable
  // image *and* as the fallback when a load fails (WMF-backed URLs etc.).
  const glyph = glyphForGrid3Image(imageRef);
  const derivedLabel = friendlyCellLabel(button.label, imageRef);
  const synthetic = isAutoGeneratedCellLabel(button.label);
  const hasVisual = !!(glyph || hasRenderableImage);
  const hideLabel = !derivedLabel && synthetic && hasVisual;
  const displayLabel = derivedLabel ?? (button.label ?? '');
  const alt = derivedLabel ?? (synthetic ? '' : (button.label ?? ''));
  return { glyph, displayLabel, hideLabel, alt };
}
